from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def read_root(my_header: str = Header(None, convert_underscores=True)):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header_accepted():
    # Current behavior: does it accept my_header when convert_underscores=True?
    response = client.get("/", headers={"my_header": "value1"})
    print(f"Response with my_header: {response.json()}")
    assert response.json()["my_header"] == "value1"

def test_hyphen_header_accepted():
    # Should accept my-header when convert_underscores=True
    response = client.get("/", headers={"my-header": "value2"})
    print(f"Response with my-header: {response.json()}")
    assert response.json()["my_header"] == "value2"

if __name__ == "__main__":
    try:
        test_underscore_header_accepted()
        print("test_underscore_header_accepted passed")
    except AssertionError as e:
        print(f"test_underscore_header_accepted failed: {e}")

    try:
        test_hyphen_header_accepted()
        print("test_hyphen_header_accepted passed")
    except AssertionError as e:
        print(f"test_hyphen_header_accepted failed: {e}")
